 elseif(isset($_SESSION['admin'])){
 if($action==='logout'){$_SESSION=[];session_destroy();header('Location: ./');exit;}
 if($action==='update' && in_array($_POST['status']??'',$statuses,true)){
 db()->beginTransaction();query('UPDATE orders SET status=?,archived=? WHERE id=?',[$_POST['status'],isset($_POST['archived'])?1:0,(int)$_POST['id']]);query('INSERT INTO audit(order_id,created_at,actor,status,note) VALUES(?,UTC_TIMESTAMP(),?,?,?)',[(int)$_POST['id'],$_SESSION['admin'],$_POST['status'],substr($_POST['note']??'',0,5000)]);db()->commit();header('Location: ./?id='.(int)$_POST['id']);exit;}
 }
 }
}catch(Throwable $e){try {if(db()->inTransaction())db()->rollBack();} catch(Throwable $ignored) {}$error='Service unavailable. Please check the server configuration.';error_log('AK dashboard: '.get_class($e));}
function token(){echo '<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'">';}
function cairoTime(string $v): string {return (new DateTimeImmutable($v,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Africa/Cairo'))->format('d M Y · H:i');}
function pageName(string $path): string {
 $name=basename(parse_url($path,PHP_URL_PATH) ?: '');
 if(!$name || $name==='index.html')return 'Home';
 $names=['sea-freight.html'=>'Sea freight','air-freight.html'=>'Air freight','land-transport.html'=>'Land transport','customs-clearance.html'=>'Customs clearance','warehousing-distribution.html'=>'Warehousing & distribution','import-export-support.html'=>'Import & export support'];
 if(isset($names[$name]))return $names[$name];
 return str_ends_with($path,'/')?'Home':$path;
}
function visitValue(array $row,string $key): string {
 if($key==='created_at')return cairoTime($row[$key]);
 if($key==='page')return pageName($row[$key]);
 if(in_array($key,['country','city'],true) && in_array($row['ip'],['::1','127.0.0.1'],true))return $key==='country'?'Local visit':'Not applicable';
 return (string)($row[$key]??'Expired');
}
